"""Demo: enumerate bracketings and confirm Catalan counts and mutual isomorphism."""
from __future__ import annotations
from dataclasses import dataclass
from math import comb
from typing import List, Union


@dataclass(frozen=True)
class Leaf:
    label: str


@dataclass(frozen=True)
class Node:
    left: "Tree"
    right: "Tree"


Tree = Union[Leaf, Node]


def flatten(t: Tree) -> List[str]:
    if isinstance(t, Leaf):
        return [t.label]
    return flatten(t.left) + flatten(t.right)


def all_bracketings(word: List[str]) -> List[Tree]:
    if len(word) == 1:
        return [Leaf(word[0])]
    out: List[Tree] = []
    for i in range(1, len(word)):
        for l in all_bracketings(word[:i]):
            for r in all_bracketings(word[i:]):
                out.append(Node(l, r))
    return out


def catalan(m: int) -> int:
    return comb(2 * m, m) // (m + 1)


def main() -> None:
    for n in range(1, 7):
        word = [chr(ord("a") + i) for i in range(n)]
        trees = all_bracketings(word)
        mutually_iso = all(flatten(trees[0]) == flatten(t) for t in trees)
        print(f"n={n}: bracketings={len(trees)} = C_{n-1}={catalan(n-1)}  "
              f"all isomorphic={mutually_iso}")


if __name__ == "__main__":
    main()

"""Demo: strictification via right-nested normal forms."""
from __future__ import annotations
from dataclasses import dataclass
from typing import List, Union


@dataclass(frozen=True)
class Leaf:
    label: str


@dataclass(frozen=True)
class Node:
    left: "Tree"
    right: "Tree"


Tree = Union[Leaf, Node]


def flatten(t: Tree) -> List[str]:
    if isinstance(t, Leaf):
        return [t.label]
    return flatten(t.left) + flatten(t.right)


def show(t: Tree) -> str:
    if isinstance(t, Leaf):
        return t.label
    return "(" + show(t.left) + show(t.right) + ")"


def of_list(word: List[str]) -> Tree:
    node: Tree = Leaf(word[-1])
    for label in reversed(word[:-1]):
        node = Node(Leaf(label), node)
    return node


def normalize(t: Tree) -> Tree:
    return of_list(flatten(t))


def all_bracketings(word: List[str]) -> List[Tree]:
    if len(word) == 1:
        return [Leaf(word[0])]
    out: List[Tree] = []
    for i in range(1, len(word)):
        for l in all_bracketings(word[:i]):
            for r in all_bracketings(word[i:]):
                out.append(Node(l, r))
    return out


def main() -> None:
    word = list("abcd")
    nf = normalize(all_bracketings(word)[0])
    for t in all_bracketings(word):
        assert flatten(normalize(t)) == flatten(t)
        print(f"{show(t):12s} ~= {show(normalize(t))}")
    print("common normal form:", show(nf))


if __name__ == "__main__":
    main()

"""Demo: verify the pentagon by checking both associator routes reach the same word."""
from __future__ import annotations
from dataclasses import dataclass
from typing import List, Union


@dataclass(frozen=True)
class Leaf:
    label: str


@dataclass(frozen=True)
class Node:
    left: "Tree"
    right: "Tree"


Tree = Union[Leaf, Node]


def flatten(t: Tree) -> List[str]:
    if isinstance(t, Leaf):
        return [t.label]
    return flatten(t.left) + flatten(t.right)


def T(a: Tree, b: Tree) -> Node:
    return Node(a, b)


def main() -> None:
    w, x, y, z = Leaf("w"), Leaf("x"), Leaf("y"), Leaf("z")
    start = T(T(T(w, x), y), z)
    end = T(w, T(x, T(y, z)))
    long_route = [start, T(T(w, T(x, y)), z), T(w, T(T(x, y), z)), end]
    short_route = [start, T(T(w, x), T(y, z)), end]
    long_ok = all(flatten(long_route[i]) == flatten(long_route[i + 1])
                  for i in range(len(long_route) - 1))
    short_ok = all(flatten(short_route[i]) == flatten(short_route[i + 1])
                   for i in range(len(short_route) - 1))
    print("long route consistent: ", long_ok)
    print("short route consistent:", short_ok)
    print("pentagon closes:       ", flatten(start) == flatten(end))


if __name__ == "__main__":
    main()

